j:jelly.g:evaluate:
        var result_macro = "cxs_result_default";
        var result_table = "";
        if (!JSUtil.nil(jelly.jvar_cxs_result.id)) {
            result_table = jelly.jvar_cxs_result.id.split(":")[0];
			var macro_label = "";
			if(result_table == 'kb_social_qa_question')
				macro_label += "sn_kb_social_qa_" ; //Add scope name.
			macro_label += "cxs_result_" + result_table;
			if(jelly.jvar_cxs_result.meta.source == "community_qa")
				macro_label = "sn_communities_cxs_cxs_result_community_qa";
			if(jelly.jvar_cxs_result.meta.source == "community_blog")
				macro_label = "sn_communities_cxs_cxs_result_community_blog";
            if (result_table) {
                var macro = GlideDBMacro.get(macro_label);
                if (macro && macro.exists())
                    result_macro = macro_label;
            }
        }
